// Generates the website Reference/Project pages from the authoritative
// repository documents. The generated files are build inputs only and are
// excluded from git; edit the root documents, never the copies.
import { cpSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const website = resolve(here, '..')
const repo = resolve(website, '..')

const pages = [
  ['docs/NUMERIC_SEMANTICS.md', 'generated/reference/NUMERIC_SEMANTICS.md'],
  ['docs/NUMERIC_DESIGN_DECISIONS.md', 'generated/reference/NUMERIC_DESIGN_DECISIONS.md'],
  ['docs/DIAGNOSTIC_CODES.md', 'generated/reference/DIAGNOSTIC_CODES.md'],
  ['docs/FEATURE_STATUS_IMPLEMENTED.md', 'generated/reference/FEATURE_STATUS_IMPLEMENTED.md'],
  ['docs/KNOWN_LIMITATIONS.md', 'generated/reference/KNOWN_LIMITATIONS.md'],
  ['docs/STAGE1_ROADMAP.md', 'generated/reference/STAGE1_ROADMAP.md'],
  ['spec/docs/LANGUAGE_SPEC.md', 'generated/reference/LANGUAGE_SPEC.md'],
  ['spec/docs/QUICK_REFERENCE.md', 'generated/reference/QUICK_REFERENCE.md'],
  ['spec/docs/JVM_INTEROP.md', 'generated/reference/JVM_INTEROP.md'],
  ['spec/docs/AGENT_TOOL_PROTOCOL.md', 'generated/reference/AGENT_TOOL_PROTOCOL.md'],
  ['spec/docs/AGENT_FRIENDLY_DECISIONS.md', 'generated/reference/AGENT_FRIENDLY_DECISIONS.md'],
  ['grammar/README.md', 'generated/reference/grammar.md'],
  ['CONTRIBUTING.md', 'generated/project/contributing.md'],
  ['AI_DISCLOSURE.md', 'generated/project/ai-disclosure.md'],
  ['LICENSE_STATUS.md', 'generated/project/license-status.md'],
  ['THIRD_PARTY_NOTICES.md', 'generated/project/third-party-notices.md']
]

const banner = (source) =>
  `<!-- Generated by website/scripts/sync-reference.mjs from ${source}. Do not edit this copy. -->\n`

// Root documents link to each other with repository-relative paths. Rewrite
// those to the website routes the generated pages actually live at.
const linkMap = new Map([
  ['README.md', '/'],
  ['LICENSE', 'https://github.com/ColinHouse/Sprig/blob/main/LICENSE'],
  ['NOTICE', 'https://github.com/ColinHouse/Sprig/blob/main/NOTICE'],
  ['CONTRIBUTING.md', '/project/contributing'],
  ['AI_DISCLOSURE.md', '/project/ai-disclosure'],
  ['LICENSE_STATUS.md', '/project/license-status'],
  ['THIRD_PARTY_NOTICES.md', '/project/third-party-notices'],
  ['docs/FEATURE_STATUS_IMPLEMENTED.md', '/reference/FEATURE_STATUS_IMPLEMENTED'],
  ['docs/FEATURE_STATUS.md', '/reference/FEATURE_STATUS_IMPLEMENTED'],
  ['docs/NUMERIC_SEMANTICS.md', '/reference/NUMERIC_SEMANTICS'],
  ['docs/NUMERIC_DESIGN_DECISIONS.md', '/reference/NUMERIC_DESIGN_DECISIONS'],
  ['docs/DIAGNOSTIC_CODES.md', '/reference/DIAGNOSTIC_CODES'],
  ['docs/KNOWN_LIMITATIONS.md', '/reference/KNOWN_LIMITATIONS'],
  ['docs/STAGE1_ROADMAP.md', '/reference/STAGE1_ROADMAP'],
  ['spec/docs/LANGUAGE_SPEC.md', '/reference/LANGUAGE_SPEC'],
  ['spec/docs/JVM_INTEROP.md', '/reference/JVM_INTEROP']
])

const rewriteLinks = (content) =>
  content.replace(/\]\(([^)\s]+)\)/g, (match, href) => {
    const [target, anchor = ''] = href.split('#')
    if (/^[a-z][a-z0-9+.-]*:/i.test(target)) return match
    const normalized = target.replace(/^(\.\.?\/)+/, '')
    const route = linkMap.get(normalized)
    if (!route) return match
    return `](${route}${anchor ? `#${anchor}` : ''})`
  })

for (const [source, target] of pages) {
  const from = join(repo, source)
  const to = join(website, target)
  mkdirSync(dirname(to), { recursive: true })
  const content = rewriteLinks(readFileSync(from, 'utf8'))
  writeFileSync(to, banner(source) + content, 'utf8')
  console.log(`synced ${source} -> website/${target}`)
}
